    prevResetBtn := resetBtn;
    normalMode := FALSE;

    // 切换拍额外处理
    ELSIF modeChanged THEN
    // flowSP保持或跟随
    IF mode = 2 THEN
        flowSP := prevFlowSP;
    ELSE
        flowSP := manualFlowSP;
    END_IF

    // 重算积分项
    iT := flowSP - KpT * (tempSP - tempPV);
    iF := valveCommand - KpF * (flowSP - flowPV);

    prevMode := mode;
    prevResetBtn := resetBtn;
    normalMode := FALSE;

    // 正常模式计算
    ELSIF NOT fault THEN
    normalMode := TRUE;

    CASE mode OF
        0:  // 手动模式
            flowSP := manualFlowSP;
            valveCommand := manualValve;
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);

        1:  // 外环手动/内环自动
            flowSP := manualFlowSP;
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);

        2:  // 串级全自动
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);
    END_CASE;

    prevMode := mode;
    prevResetBtn := resetBtn;
END_IF
